 function finishDraft(){if(!draft)return toast('Start drawing first');const min=draft.geometry==='Polygon'?3:draft.geometry==='LineString'?2:1;if(draft.coords.length<min)return toast(`Need at least ${min} point(s)`);draft.properties.name=$('featureName').value.trim()||draft.properties.name||typeInfo[draft.type][0];draft.properties.remark=$('featureRemark').value.trim();const f={id:editingId||uid('feature'),layerId:draft.layerId,type:draft.type,geometry:draft.geometry,coords:draft.coords.map(x=>x.slice()),vertexLocks:draft.locks.slice(),locked:false,properties:{...draft.properties},created:new Date().toISOString()};if(f.geometry==='Polygon'&&$('autoFit').checked&&targetM2()>0){const fit=fitCoords(f.coords,f.vertexLocks,targetM2());if(!fit.ok)return toast(fit.error);f.coords=fit.coords;showFitPreview(f,!!editingId);return}addOrReplace(f)}
 function fitCoords(coords,locks,target){const cur=ringArea(coords),fixed=coords.filter((_,i)=>locks[i]);if(fixed.length===coords.length)return Math.abs(cur-target)<.05?{ok:true,coords}:{ok:false,error:'All vertices are snapped/locked'};const c=centroid(fixed.length?fixed:coords),lat=c[1],mlon=111320*Math.cos(lat*Math.PI/180),mlat=110540,at=k=>coords.map((p,i)=>locks[i]?p.slice():[c[0]+((p[0]-c[0])*mlon*k)/mlon,c[1]+((p[1]-c[1])*mlat*k)/mlat]);let lo=0,hi=1,a0=ringArea(at(0)),ah=ringArea(at(1));if(target<a0-.05)return{ok:false,error:'Target is too small while snapped points stay fixed'};while(ah<target&&hi<1024){hi*=2;ah=ringArea(at(hi))}if(ah<target)return{ok:false,error:'Target cannot be reached'};for(let i=0;i<70;i++){const m=(lo+hi)/2;if(ringArea(at(m))<target)lo=m;else hi=m}return{ok:true,coords:at((lo+hi)/2)}}
