 function tracePath(f,s,e){const c=f.coords,n=c.length,closed=f.geometry==='Polygon';if(!closed){const a=s.segment+s.t,b=e.segment+e.t,out=[ [s.ll.lng,s.ll.lat] ];if(a<=b){for(let i=s.segment+1;i<=e.segment;i++)out.push(c[i].slice())}else{for(let i=s.segment;i>e.segment;i--)out.push(c[i].slice())}out.push([e.ll.lng,e.ll.lat]);return out}const forward=[[s.ll.lng,s.ll.lat]];let seg=s.segment;while(seg!==e.segment){forward.push(c[(seg+1)%n].slice());seg=(seg+1)%n;if(forward.length>n+2)break}forward.push([e.ll.lng,e.ll.lat]);const reverse=[[s.ll.lng,s.ll.lat]];seg=s.segment;while(seg!==e.segment){reverse.push(c[seg].slice());seg=(seg-1+n)%n;if(reverse.length>n+2)break}reverse.push([e.ll.lng,e.ll.lat]);return lineLength(forward)<=lineLength(reverse)?forward:reverse}
