 function secure(){return window.isSecureContext||location.hostname==='localhost'||location.hostname==='127.0.0.1'}
 function locate(cb,center=false){if(!secure())return toast('GPS requires the HTTPS GitHub Pages link');navigator.geolocation.getCurrentPosition(p=>{lastGps=p;showGps(p,center);$('gpsStatus').textContent=`±${p.coords.accuracy.toFixed(1)} m · ${new Date(p.timestamp).toLocaleTimeString()}`;if(cb)cb(p)},e=>toast('GPS: '+e.message),{enableHighAccuracy:true,timeout:20000,maximumAge:0})}
 function showGps(p,center){gpsGroup.clearLayers();const ll=[p.coords.latitude,p.coords.longitude];L.circle(ll,{radius:p.coords.accuracy,color:'#6eb7ff',weight:1,fillOpacity:.1}).addTo(gpsGroup);L.marker(ll,{icon:L.divIcon({className:'',html:'<div class="gpspulse"></div>',iconSize:[18,18],iconAnchor:[9,9]})}).addTo(gpsGroup);if(center)map.setView(ll,19)}
 $('gpsFab').onclick=()=>locate(null,true);
 function nextPointNo(){const nums=project.features.filter(f=>f.geometry==='Point').map(f=>parseInt(f.properties?.number,10)).filter(Number.isFinite);return String((nums.length?Math.max(...nums):0)+1)}
 function saveSurveyPoint(c,p){if(!ensureProject())return;const code=$('pointCode').value.trim(),num=$('pointNo').value.trim()||nextPointNo(),f={id:uid('feature'),layerId:$('surveyLayer').value||activeDrawLayer('point').id,type:'point',geometry:'Point',coords:[c],vertexLocks:[false],locked:false,properties:{name:num,number:num,code,remark:$('pointRemark').value.trim(),accuracy:p?+p.coords.accuracy.toFixed(3):null,source:p?'GPS':'map'},created:new Date().toISOString()};project.features.push(f);selectedId=f.id;$('pointNo').value=String((parseInt(num,10)||0)+1);mode='select';autosave();renderAll();toast(`Point ${num} saved`)}
 function surveySpec(method=$('surveyMethod').value){if(method==='line')return{type:'boundary',geometry:'LineString',min:2,max:2};if(method==='polyline')return{type:'custom-line',geometry:'LineString',min:2,max:Infinity};if(method==='polygon')return{type:'parcel',geometry:'Polygon',min:3,max:Infinity};return{type:'point',geometry:'Point',min:1,max:1}}
 function ensureSurveyDraft(method=$('surveyMethod').value){const s=surveySpec(method);if(s.geometry==='Point')return null;if(draft&&draft.surveySession&&draft.geometry===s.geometry&&draft.type===s.type)return draft;if(draft&&draft.coords.length&&!confirm('Clear the current unfinished geometry and start this survey session?'))return null;draft={type:s.type,geometry:s.geometry,coords:[],locks:[],layerId:$('surveyLayer').value||activeDrawLayer(s.type).id,properties:{name:$('pointNo').value.trim()||s.type,code:$('pointCode').value.trim(),remark:$('pointRemark').value.trim()},surveySession:true};editingId='';renderDraft();return draft}
 function addSurveyCoordinate(c,p=null){const method=$('surveyMethod').value,s=surveySpec(method);if(method==='point')return saveSurveyPoint(c,p);const d=ensureSurveyDraft(method);if(!d)return;if(Number.isFinite(s.max)&&d.coords.length>=s.max)return toast('Line already has 2 points — Finish or use Polyline');d.coords.push(c);d.locks.push($('lockNewVertices').checked);renderDraft();if(s.max===2&&d.coords.length===2)toast('Line has 2 points — press Finish Geometry')}
 function finishSurveyGeometry(){if(!draft?.surveySession)return toast('No active survey geometry');const s=surveySpec(),n=draft.coords.length;if(n<s.min)return toast(`Need at least ${s.min} point(s)`);if(Number.isFinite(s.max)&&n>s.max)return toast(`Line method accepts exactly ${s.max} points; use Polyline`);const num=$('pointNo').value.trim()||`${typeInfo[draft.type]?.[0]} ${project.features.length+1}`,f={id:uid('feature'),layerId:$('surveyLayer').value||draft.layerId,type:draft.type,geometry:draft.geometry,coords:draft.coords.map(x=>x.slice()),vertexLocks:draft.locks.slice(),locked:false,properties:{name:num,number:num,code:$('pointCode').value.trim(),remark:$('pointRemark').value.trim(),source:'survey'},created:new Date().toISOString()};project.features.push(f);selectedId=f.id;clearDraft();autosave();renderAll();selectFeature(f.id);toast(`${f.geometry} saved · ${geomMeta(f)}`)}
 $('gpsPointBtn').onclick=()=>locate(p=>addSurveyCoordinate([p.coords.longitude,p.coords.latitude],p),true);$('tapPointBtn').onclick=()=>{if(!ensureProject())return;mode='surveyTap';toast('Tap map to add the next survey position')};
