 $('surveyFinishBtn').onclick=finishSurveyGeometry;$('surveyUndoBtn').onclick=()=>{if(draft?.surveySession&&draft.coords.length){draft.coords.pop();draft.locks.pop();renderDraft()}else toast('No survey point to undo')};$('surveyClearBtn').onclick=()=>{if(draft?.surveySession)clearDraft();toast('Survey session cleared')};$('surveyToMapBtn').onclick=()=>{if(!selectedId)return toast('Finish or select a polygon first');switchTab('mapPage');toast('Selected feature is ready for Auto Fit or Area Split')};
 function rebuildAssembly(){assembleCoords=[];let gapMax=0;assembleIds.forEach(id=>{const f=feature(id);if(!f)return;let part=f.geometry==='Point'?[f.coords[0].slice()]:f.coords.map(x=>x.slice());if(assembleCoords.length&&part.length){const end=assembleCoords.at(-1),d1=distance(end,part[0]),d2=distance(end,part.at(-1));if(d2<d1)part.reverse();gapMax=Math.max(gapMax,Math.min(d1,d2));if(distance(end,part[0])<.05)part.shift()}assembleCoords.push(...part)});previewGroup.clearLayers();if(assembleCoords.length>1){const lat=assembleCoords.map(p=>[p[1],p[0]]);($('joinOutput').value==='polygon'&&assembleCoords.length>=3?L.polygon(lat,{color:'#ffb64d',weight:4,fillOpacity:.16}):L.polyline(lat,{color:'#ffb64d',weight:4})).addTo(previewGroup)}const measure=$('joinOutput').value==='polygon'&&assembleCoords.length>=3?arpText(ringArea(assembleCoords)):lineLength(assembleCoords).toFixed(2)+' m';$('assembleStatus').textContent=`${assembleIds.length} selected · ${assembleCoords.length} vertices · ${measure}${gapMax>.25?' · gap '+gapMax.toFixed(2)+'m':''}`;renderMap()}
 function assembleFeature(id){const f=feature(id);if(!f||!['Point','LineString'].includes(f.geometry))return toast('Select survey points or boundary lines only');const i=assembleIds.indexOf(id);if(i>=0)assembleIds.splice(i,1);else assembleIds.push(id);rebuildAssembly()}
 $('assembleBtn').onclick=()=>{if(!ensureProject())return;assembleIds=[];assembleCoords=[];mode='assemble';rebuildAssembly();toast('Tap required points/lines in joining order')};$('joinOutput').onchange=rebuildAssembly;$('assembleClearBtn').onclick=()=>{assembleIds=[];assembleCoords=[];previewGroup.clearLayers();mode='select';$('assembleStatus').textContent='Selection cleared';renderMap()};$('assembleFinishBtn').onclick=()=>{const poly=$('joinOutput').value==='polygon',min=poly?3:2;if(assembleCoords.length<min)return toast(`Select enough points/lines (${min}+ vertices)`);const num=$('pointNo').value.trim()||(poly?'Joined Parcel':'Joined Boundary'),dest=project.layers.find(x=>!x.locked&&x.kind===(poly?'parcel':'line'))||layer($('surveyLayer').value),f={id:uid('feature'),layerId:dest.id,type:poly?'parcel':'boundary',geometry:poly?'Polygon':'LineString',coords:assembleCoords.map(x=>x.slice()),vertexLocks:assembleCoords.map(()=>false),locked:false,properties:{name:num,number:num,code:$('pointCode').value.trim(),remark:$('pointRemark').value.trim(),source:'joined survey features'},created:new Date().toISOString()};project.features.push(f);selectedId=f.id;assembleIds=[];assembleCoords=[];previewGroup.clearLayers();mode='select';autosave();renderAll();selectFeature(f.id);toast(`${poly?'Polygon':'Polyline'} joined; source features kept`)};
 $('addCodeBtn').onclick=()=>{const v=prompt('New point/feature code',$('pointCode').value||'');if(!v)return;let c;try{c=JSON.parse(localStorage.getItem(CODES_KEY)||'["BP","CP","TP","RL","ROAD","STREAM"]')}catch(e){c=['BP','CP','TP','RL','ROAD','STREAM']}if(!c.includes(v.trim()))c.push(v.trim());localStorage.setItem(CODES_KEY,JSON.stringify(c));$('pointCode').value=v.trim();renderCodes()};
 function walkAdd(p,force){lastGps=p;showGps(p,false);const max=+$('maxAccuracy').value||5;if(p.coords.accuracy>max&&!force){$('walkStatus').textContent=`Skipped ±${p.coords.accuracy.toFixed(1)}m`;return}const c=[p.coords.longitude,p.coords.latitude],min=+$('walkDistance').value||1;if(!force&&draft.coords.length&&distance(draft.coords.at(-1),c)<min)return;draft.coords.push(c);draft.locks.push($('lockNewVertices').checked);renderDraft();$('walkStatus').textContent=`Recording · ${draft.coords.length} pts · ±${p.coords.accuracy.toFixed(1)}m`}
 $('walkStartBtn').onclick=()=>{if(!ensureProject()||!secure())return toast('GPS walk requires HTTPS');if(walkId!==null)return;$('surveyMethod').value='polygon';$('surveyMethod').dataset.prev='polygon';setSurveyLayerForMethod();if(!ensureSurveyDraft('polygon'))return;mode='walk';walkId=navigator.geolocation.watchPosition(p=>walkAdd(p,false),e=>toast('GPS: '+e.message),{enableHighAccuracy:true,timeout:20000,maximumAge:0});$('walkStatus').textContent='Recording…';toast('GPS boundary walk started')};$('walkRecordBtn').onclick=()=>{if(lastGps&&draft)walkAdd(lastGps,true);else locate(p=>{if(!draft){$('surveyMethod').value='polygon';setSurveyLayerForMethod();ensureSurveyDraft('polygon')}walkAdd(p,true)})};$('walkStopBtn').onclick=()=>{if(walkId!==null){navigator.geolocation.clearWatch(walkId);walkId=null}$('walkStatus').textContent=`Stopped · ${draft?.coords.length||0} points`;if(draft?.coords.length>=3)finishSurveyGeometry();else toast('Need at least 3 positions')};

 function addLayer(name,kind='line',color='#bd8cff',source='survey'){const l={id:uid('lyr'),name,kind,color,visible:true,locked:false,snap:true,export:true,source};project.layers.push(l);return l}
 $('addLayerBtn').onclick=()=>{if(!ensureProject())return;const n=prompt('New layer name','Additional Features');if(!n)return;const kind=prompt('Layer kind: parcel, line, point, reference','line')||'line',c=prompt('Colour (#RRGGBB)','#bd8cff')||'#bd8cff';addLayer(n,kind,/^#[0-9a-f]{6}$/i.test(c)?c:'#bd8cff');autosave();renderAll()};
 function parseKML(t){const d=new DOMParser().parseFromString(t,'application/xml');if(d.querySelector('parsererror'))throw Error('Invalid KML');const out=[];d.querySelectorAll('Placemark').forEach(pm=>{const name=pm.querySelector('name')?.textContent||'',remark=pm.querySelector('description')?.textContent||'';['Polygon','LineString','Point'].forEach(g=>{pm.querySelectorAll(g).forEach(el=>{const ce=el.querySelector('coordinates');if(!ce)return;let c=ce.textContent.trim().split(/\s+/).map(x=>x.split(',')).filter(x=>Number.isFinite(+x[0])&&Number.isFinite(+x[1])).map(x=>[+x[0],+x[1]]);if(g==='Polygon'&&c.length>1&&distance(c[0],c.at(-1))<.01)c.pop();if(c.length)out.push({geometry:g,coords:c,name,remark})})})});return out}
 function importKML(t,name){const a=parseKML(t);if(!a.length)throw Error('No supported KML geometry');const l=addLayer(name.replace(/\.kml$/i,''),'reference','#bd8cff','KML');a.forEach((x,i)=>project.features.push({id:uid('feature'),layerId:l.id,type:x.geometry==='Polygon'?'parcel':x.geometry==='Point'?'point':'custom-line',geometry:x.geometry,coords:x.coords,vertexLocks:x.coords.map(()=>false),locked:false,properties:{name:x.name||`${l.name} ${i+1}`,remark:x.remark},created:new Date().toISOString()}));autosave();renderAll();map.fitBounds(L.latLngBounds(a.flatMap(x=>x.coords).map(p=>[p[1],p[0]])),{padding:[25,25]});toast(`${a.length} KML feature(s) imported`)}
 function dxfPairs(t){const a=t.replace(/\r/g,'').split('\n'),p=[];for(let i=0;i+1<a.length;i+=2)p.push([a[i].trim(),a[i+1].trim()]);return p}
 function parseDXF(t){const p=dxfPairs(t),out=[];for(let i=0;i<p.length;i++){if(p[i][0]!=='0')continue;const typ=p[i][1];if(typ==='LWPOLYLINE'){let c=[],x=null,l='0',closed=false;i++;for(;i<p.length&&p[i][0]!=='0';i++){if(p[i][0]==='8')l=p[i][1];if(p[i][0]==='70')closed=(+p[i][1]&1)!==0;if(p[i][0]==='10')x=+p[i][1];if(p[i][0]==='20'&&x!==null){c.push([x,+p[i][1]]);x=null}}i--;if(c.length>=2)out.push({layer:l,geometry:closed?'Polygon':'LineString',xy:c})}else if(typ==='POLYLINE'){let c=[],l='0',closed=false,header=true;i++;for(;i<p.length;i++){if(header&&p[i][0]==='8')l=p[i][1];if(header&&p[i][0]==='70')closed=(+p[i][1]&1)!==0;if(p[i][0]==='0'&&p[i][1]==='SEQEND')break;if(p[i][0]==='0'&&p[i][1]==='VERTEX'){header=false;let x,y;i++;for(;i<p.length&&p[i][0]!=='0';i++){if(p[i][0]==='10')x=+p[i][1];if(p[i][0]==='20')y=+p[i][1]}i--;if(Number.isFinite(x)&&Number.isFinite(y))c.push([x,y])}}if(c.length>=2)out.push({layer:l,geometry:closed?'Polygon':'LineString',xy:c})}else if(typ==='LINE'||typ==='POINT'){let l='0',x,y,x2,y2;i++;for(;i<p.length&&p[i][0]!=='0';i++){if(p[i][0]==='8')l=p[i][1];if(p[i][0]==='10')x=+p[i][1];if(p[i][0]==='20')y=+p[i][1];if(p[i][0]==='11')x2=+p[i][1];if(p[i][0]==='21')y2=+p[i][1]}i--;if(Number.isFinite(x)&&Number.isFinite(y))out.push({layer:l,geometry:typ==='POINT'?'Point':'LineString',xy:typ==='POINT'?[[x,y]]:[[x,y],[x2,y2]]})}}return out}
 function importDXF(t,name){if(!window.proj4)throw Error('SLD99 converter unavailable');const a=parseDXF(t);if(!a.length)throw Error('No supported DXF geometry');const lm={};a.forEach(x=>{if(!lm[x.layer])lm[x.layer]=addLayer(x.layer||name.replace(/\.dxf$/i,''),'reference','#bd8cff','DXF · SLD99');const c=x.xy.map(fromSLD);project.features.push({id:uid('feature'),layerId:lm[x.layer].id,type:x.geometry==='Polygon'?'parcel':x.geometry==='Point'?'point':'custom-line',geometry:x.geometry,coords:c,vertexLocks:c.map(()=>false),locked:false,properties:{name:x.layer||'DXF feature',remark:'Imported '+name},created:new Date().toISOString()})});autosave();renderAll();const c=a.flatMap(x=>x.xy).map(fromSLD);map.fitBounds(L.latLngBounds(c.map(p=>[p[1],p[0]])),{padding:[25,25]});toast(`${a.length} DXF feature(s), ${Object.keys(lm).length} layer(s) imported`)}
 function chooseFile(m,accept){fileMode=m;$('fileInput').accept=accept;$('fileInput').value='';$('fileInput').click()}
 $('importKmlBtn').onclick=()=>{if(ensureProject())chooseFile('kml','.kml')};$('importDxfBtn').onclick=()=>{if(ensureProject())chooseFile('dxf','.dxf')};$('projectImportBtn').onclick=()=>chooseFile('project','.json,.fieldsketch');
 $('fileInput').onchange=async()=>{const f=$('fileInput').files[0];if(!f)return;try{const t=await f.text();if(fileMode==='kml')importKML(t,f.name);else if(fileMode==='dxf')importDXF(t,f.name);else{const p=JSON.parse(t);if(p.schema!=='fieldsketch-project'||!Array.isArray(p.layers)||!Array.isArray(p.features))throw Error('Not a FieldSketch project');p.id=uid('project');p.name=(p.name||'Imported Project')+' (Imported)';projects[p.id]=p;localStorage.setItem(PROJECTS_KEY,JSON.stringify(projects));switchProject(p.id);saveNow();toast('Complete project imported')}}catch(e){toast('Import failed: '+e.message)}};
 function exportFeatures(){return project.features.filter(f=>{const l=layer(f.layerId);return l?.visible&&l.export})}
 function kmlText(){let folders='';project.layers.filter(l=>l.visible&&l.export).forEach(l=>{let body='';project.features.filter(f=>f.layerId===l.id).forEach(f=>{const n=xml(f.properties?.name||typeInfo[f.type]?.[0]),r=xml(f.properties?.remark||''),style=`<Style><LineStyle><color>ff${l.color.slice(5,7)}${l.color.slice(3,5)}${l.color.slice(1,3)}</color><width>3</width></LineStyle><PolyStyle><color>44${l.color.slice(5,7)}${l.color.slice(3,5)}${l.color.slice(1,3)}</color></PolyStyle></Style>`,desc=`<description>${r}</description><ExtendedData><Data name="layer"><value>${xml(l.name)}</value></Data><Data name="type"><value>${xml(f.type)}</value></Data><Data name="locked"><value>${f.locked}</value></Data></ExtendedData>`;if(f.geometry==='Point'){const p=f.coords[0];body+=`<Placemark><name>${n}</name>${style}${desc}<Point><coordinates>${p[0]},${p[1]},0</coordinates></Point></Placemark>`}else{let c=f.coords.slice();if(f.geometry==='Polygon')c=c.concat([c[0]]);const cs=c.map(p=>`${p[0].toFixed(9)},${p[1].toFixed(9)},0`).join(' ');body+=`<Placemark><name>${n}</name>${style}${desc}<${f.geometry}>${f.geometry==='Polygon'?'<outerBoundaryIs><LinearRing>':''}<coordinates>${cs}</coordinates>${f.geometry==='Polygon'?'</LinearRing></outerBoundaryIs>':''}</${f.geometry}></Placemark>`}});folders+=`<Folder><name>${xml(l.name)}</name>${body}</Folder>`});return`<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>${xml(project.name)}</name>${folders}</Document></kml>`}
 function dxfText(){const pair=(c,v)=>`${c}\n${String(v).replace(/[\r\n]+/g,' ')}\n`;let e='';exportFeatures().forEach(f=>{const l=layer(f.layerId),ln=(l.name||'0').replace(/[^A-Za-z0-9_-]/g,'_').slice(0,31),q=f.coords.map(toSLD);if(f.geometry==='Point')e+=pair(0,'POINT')+pair(8,ln)+pair(10,q[0][0].toFixed(3))+pair(20,q[0][1].toFixed(3))+pair(30,0);else{e+=pair(0,'POLYLINE')+pair(8,ln)+pair(66,1)+pair(70,f.geometry==='Polygon'?1:0);q.forEach(p=>e+=pair(0,'VERTEX')+pair(8,ln)+pair(10,p[0].toFixed(3))+pair(20,p[1].toFixed(3))+pair(30,0));e+=pair(0,'SEQEND')}if(f.properties?.name){const c=f.geometry==='Point'?q[0]:toSLD(centroid(f.coords));e+=pair(0,'TEXT')+pair(8,ln)+pair(10,c[0].toFixed(3))+pair(20,c[1].toFixed(3))+pair(30,0)+pair(40,2)+pair(1,f.properties.name)}});return pair(0,'SECTION')+pair(2,'HEADER')+pair(9,'$ACADVER')+pair(1,'AC1009')+pair(0,'ENDSEC')+pair(0,'SECTION')+pair(2,'ENTITIES')+e+pair(0,'ENDSEC')+pair(0,'EOF')}
 function csvText(){let s='Layer,Feature,Geometry,Point,Code,Remark,Latitude_WGS84,Longitude_WGS84,Easting_SLD99,Northing_SLD99,Accuracy_m\r\n';exportFeatures().forEach(f=>f.coords.forEach((p,i)=>{const en=toSLD(p),v=x=>'"'+String(x??'').replace(/"/g,'""')+'"';s+=[v(layer(f.layerId).name),v(f.properties?.name),v(f.geometry),i+1,v(f.properties?.code),v(f.properties?.remark),p[1].toFixed(7),p[0].toFixed(7),en[0].toFixed(3),en[1].toFixed(3),f.properties?.accuracy??''].join(',')+'\r\n'}));return s}
 const safeName=()=>project.name.replace(/[^\p{L}\p{N}_-]+/gu,'_');
 function backup(){saveNow();download(JSON.stringify(project,null,2),safeName()+'.fieldsketch.json','application/json')}
 $('projectBackupBtn').onclick=backup;$('exportKmlBtn').onclick=()=>download(kmlText(),safeName()+'.kml','application/vnd.google-earth.kml+xml');$('exportDxfBtn').onclick=()=>{try{download(dxfText(),safeName()+'_SLD99.dxf','application/dxf')}catch(e){toast(e.message)}};$('exportCsvBtn').onclick=()=>{try{download(csvText(),safeName()+'_coordinates.csv','text/csv')}catch(e){toast(e.message)}};
 $('shareBtn').onclick=async()=>{if(!project)return;const f=new File([JSON.stringify(project,null,2)],safeName()+'.fieldsketch.json',{type:'application/json'});if(navigator.canShare?.({files:[f]})){try{await navigator.share({title:project.name,text:'FieldSketch project backup',files:[f]})}catch(e){if(e.name!=='AbortError')toast('Share failed')}}else{backup();toast('Project downloaded; share it from Downloads')}};

 $('newProjectBtn').onclick=()=>$('projectModal').classList.add('show');$('openProjectBtn').onclick=openProjectDialog;$('projectChip').onclick=openProjectDialog;$('renameProjectBtn').onclick=()=>{if(!project)return;const n=prompt('Project name',project.name);if(n){project.name=n;autosave();renderAll()}};
 $('menuBtn').onclick=()=> $('mainMenu').classList.toggle('show');$('mainMenu').onclick=e=>{const a=e.target.dataset.act;$('mainMenu').classList.remove('show');if(a==='new-project')$('projectModal').classList.add('show');if(a==='open-project')openProjectDialog();if(a==='save-project'&&project)backup();if(a==='import-project')chooseFile('project','.json,.fieldsketch');if(a==='export-share')switchTab('projectPage')};
 $('addLayerBtn').disabled=false;
 ['A','R','P'].forEach(id=>$(id).oninput=()=>$('targetArea').textContent=arpText(targetM2()));
 function switchTab(id){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('on',x.dataset.tab===id));document.querySelectorAll('.tabpage').forEach(x=>x.classList.toggle('on',x.id===id));syncPanel()}
 $('tabs').onclick=e=>{const b=e.target.closest('.tab');if(b)switchTab(b.dataset.tab)};
 const panel=$('panel');function syncPanel(){const h=panel.classList.contains('collapsed')?38:Math.min(panel.offsetHeight,innerHeight*.44);document.documentElement.style.setProperty('--panelH',h+'px');setTimeout(()=>map.invalidateSize(),220)}function togglePanel(){panel.classList.toggle('collapsed');$('panelFab').firstChild.nodeValue=panel.classList.contains('collapsed')?'▴':'▾';syncPanel()}$('panelFab').onclick=togglePanel;$('grip').onclick=togglePanel;addEventListener('resize',syncPanel);new ResizeObserver(syncPanel).observe(panel);
 function closeModal(id){$(id).classList.remove('show')}
 const last=localStorage.getItem(ACTIVE_KEY);if(last&&projects[last])switchProject(last);else openProjectDialog();renderCodes();syncPanel();if(!window.proj4)setTimeout(()=>toast('SLD99 converter unavailable — check internet once'),700)
